!function(){if(!("serviceWorker"in navigator))return;window.addEventListener("load",()=>{navigator.serviceWorker.register("/sw.js").catch(()=>{})});let p=null;window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();p=e;window.woongbiInstallApp=async()=>{if(!p)return!1;p.prompt();const r=await p.userChoice;p=null;return"accepted"===r.outcome}});window.addEventListener("appinstalled",()=>{p=null;window.dispatchEvent(new CustomEvent("woongbi:pwa-installed"))})}();
